require dirname(__DIR__).'/includes/bootstrap.php';require_permission('drivers.edit');verify_csrf();ensure_runtime_schema();$id=(int)($_POST['id']??0);if($id<1){flash('error','Invalid daily count.');redirect('drivers.php');}try{$pdo=db();$q=$pdo->prepare('SELECT activity_date,customers_registered,drivers_registered FROM daily_growth_counts WHERE id=?');$q->execute([$id]);$row=$q->fetch();if(!$row)throw new RuntimeException('Daily count was not found.');$pdo->prepare('DELETE FROM daily_growth_counts WHERE id=?')->execute([$id]);audit('growth_count.deleted','daily_growth_count',$id,$row);flash('success','Daily count deleted.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('drivers.php');
